def is_ours(text):
    """True for shortcuts written by this app (or by the older versions of this app)."""
    return MARK in text or any(m in text for m in LEGACY_MARKS)


def is_ours_xml(text):
    return XML_MARK in text or any(m in text for m in LEGACY_XML_MARKS)


def profile(cfg):
    return PROFILES.get(cfg.get("profile", "knulli"), PROFILES["knulli"])


