def config_dir():
    """Per-user settings folder (the .exe may live in a read-only place and its temp folder is wiped on exit)."""
    override = os.environ.get("PORTMASTERFORWARDER_HOME") or os.environ.get("PORTFORWARDER_HOME")
    if override:
        return Path(override)
    if sys.platform.startswith("win"):
        base = os.environ.get("APPDATA") or str(Path.home() / "AppData" / "Roaming")
    elif sys.platform == "darwin":
        base = str(Path.home() / "Library" / "Application Support")
    else:
        base = os.environ.get("XDG_CONFIG_HOME") or str(Path.home() / ".config")
    return Path(base) / "PortMasterForwarder"


def config_path():
    return config_dir() / CONFIG_NAME


def legacy_config_dirs():
    """Folders where earlier versions kept their settings file (next to the program)."""
    dirs = []
    try:
        dirs.append(Path(sys.executable).resolve().parent if getattr(sys, "frozen", False) else Path(sys.argv[0]).resolve().parent)
    except (OSError, IndexError):
        pass
    dirs.append(Path.cwd())
    dirs.append(config_dir().parent / "PortForwarder")      # settings folder of the previous project name
    return dirs


def resource_path(relative):
    """Absolute path of a file shipped inside the package (works from source and inside the .exe)."""
    return Path(__file__).resolve().parent / relative


def load_config(path, search_dirs=()):
    """Load settings from `path`. If it does not exist yet, settings from the older file names
    (and from `search_dirs`) are imported once; the next save writes the new file."""
    cfg = json.loads(json.dumps(DEFAULT_CONFIG))
    p = Path(path)
    candidates = [p, p.with_name(PREVIOUS_CONFIG_NAME), p.with_name(LEGACY_CONFIG_NAME)]
    for d in search_dirs:
        candidates += [Path(d) / CONFIG_NAME, Path(d) / PREVIOUS_CONFIG_NAME, Path(d) / LEGACY_CONFIG_NAME]
    for cand in candidates:
        if cand.exists():
            try:
                data = json.loads(cand.read_text(encoding="utf-8"))
                cfg.update({k: v for k, v in data.items() if k in cfg})
            except (OSError, ValueError):
                continue
            break
    cfg["steam_lang"] = METADATA_LANG        # generated metadata is always English
    return cfg


def save_config(cfg, path):
    Path(path).parent.mkdir(parents=True, exist_ok=True)
    Path(path).write_text(json.dumps(cfg, indent=2, ensure_ascii=False), encoding="utf-8")


def game_state(cfg, nome):
    st = dict(DEFAULT_GAME)
    st.update(cfg["games"].get(nome, {}))
    return st


