FRIENDLY_THEMES = [  # (text shown, theme key)
    ("GameCube", "gc"), ("PlayStation 2", "ps2"), ("PC - Steam style", "steam"), ("PC - DOS style", "pc"),
    ("PC - Windows", "windows"), ("Wii", "wii"), ("Wii U", "wiiu"), ("Nintendo 64", "n64"), ("Nintendo 3DS", "3ds"), ("Nintendo Switch", "switch"),
    ("PlayStation", "psx"), ("PlayStation 3", "ps3"), ("PSP", "psp"), ("PS Vita", "psvita"), ("Xbox", "xbox"),
    ("Xbox 360", "xbox360"), ("Dreamcast", "dreamcast"), ("Android", "android"), ("Ports (default)", "ports"),
]


def theme_label(key):
    for text, k in FRIENDLY_THEMES:
        if k == key:
            return "%s  (%s)" % (text, k)
    return key


def theme_from_label(text):
    """'Wii  (wii)' -> 'wii'; free text is used as the key itself."""
    m = re.search(r"\(([^()]+)\)\s*$", text)
    return (m.group(1) if m else text).strip()


def platform_for_theme(key):
    return {"gc": "gamecube", "steam": "pc", "pc": "pc", "windows": "pc"}.get(key, key)


def slug_folder(name, existing):
    base = "port" + (re.sub(r"[^a-z0-9]", "", name.lower()) or "novo")
    cand, i = base, 2
    while cand in existing:
        cand, i = "%s%d" % (base, i), i + 1
    return cand


def default_term(nome):
    """'StardewValley.sh' -> 'Stardew Valley' (initial search term)."""
    base = nome[:-3] if nome.lower().endswith(".sh") else nome
    if re.match(r"(?i)^minecraft[\s_]+v?\d", base):   # MCPE version shortcuts: search the game, not the version
        return "Minecraft"
    return re.sub(r"(?<=[a-z])(?=[A-Z])", " ", base.replace("_", " ")).strip()


def find_share_candidates():
    """Look for Windows drive letters containing roms\\ports - normally the SD card."""
    import os
    out = []
    for letter in "DEFGHIJKLMNOPQRSTUVWXYZ":
        root = "%s:\\" % letter
        try:
            if os.path.isdir(os.path.join(root, "roms", "ports")):
                out.append(root)
        except OSError:
            pass
    return out


# ----------------------------------------------------------------------------
# PATHS
# ----------------------------------------------------------------------------
def get_path(cfg, key):
    """Path chosen by the user or, when empty, derived from the SHARE folder."""
    if cfg.get(key):
        return Path(cfg[key])
    if cfg.get("share"):
        return Path(cfg["share"]) / profile(cfg)["rel"][key]
    return None


def cat_by_folder(cfg, folder):
    for c in cfg["categories"]:
        if c["folder"] == folder:
            return c
    return None


def cat_dir(cfg, cat):
    return get_path(cfg, "roms_dir") / cat["folder"]


def device_ports_path(cfg):
    """Path of the ports folder INSIDE the handheld (e.g. /userdata/roms/ports)."""
    ports, roms = get_path(cfg, "ports_dir"), get_path(cfg, "roms_dir")
    try:
        rel = ports.relative_to(roms).as_posix()
    except (ValueError, AttributeError):
        rel = "ports"
    return profile(cfg)["device_roms"] + "/" + rel


# ----------------------------------------------------------------------------
# GAME DISCOVERY / CURRENT STATE
# ----------------------------------------------------------------------------
def _mcpe_name(version):
    base = version if version.lower().startswith("minecraft") else "Minecraft " + version
    return re.sub(r'[<>:/|?*]', "_", base) + ".sh"


def mcpe_virtual(cfg):
    """{shortcut_name: (launcher_script_name, version)} for the MCPE Launcher versions found on the card.
    Empty when the option is off, or the launcher script or its versions folder is missing."""
    ports = get_path(cfg, "ports_dir")
    if not cfg.get("mcpe_versions", True) or not ports or not ports.is_dir():
        return {}
    script = next((f.name for f in ports.iterdir()
                   if f.is_file() and f.name.lower() == MCPE_SCRIPT), None)
    vdir = ports.joinpath(*MCPE_VERSIONS_REL)
    if not script or not vdir.is_dir():
        return {}
    out = {}
    for d in sorted(vdir.iterdir(), key=lambda p: p.name.lower()):
        v = d.name
        if (not d.is_dir() or v.startswith(".") or re.search(r'[$`"\\]', v)
                or not any((d / sub).is_dir() for sub in ("lib", "assets"))):
            continue
        out[_mcpe_name(v)] = (script, v)
    return out


def shortcut_key(text):
    """Game name a shortcut stands for: the original script, or the virtual MCPE version name."""
    m = TARGET_RE.search(text)
    if not m:
        return None
    v = VERSION_RE.search(text)
    return _mcpe_name(v.group(1).strip()) if v else m.group(1)


def list_games(cfg):
    ports = get_path(cfg, "ports_dir")
    ignore = {x.strip().lower() for x in cfg.get("ignore", []) if x.strip()}
    out = []
    if ports and ports.is_dir():
        for f in sorted(ports.iterdir(), key=lambda p: p.name.lower()):
            if (f.is_file() and f.suffix.lower() == ".sh" and not f.name.startswith("._")
                    and f.name.lower() not in ignore):
                out.append(f.name)
        out += [n for n in mcpe_virtual(cfg) if n not in out]
    return out


def _cfg_info(cfg, folder):
    """name/theme from an existing es_systems cfg of that folder (hand-made ones included)."""
    info = {}
    d = get_path(cfg, "es_cfg_dir")
    for p in ([d / profile(cfg)["system_cfg"].format(folder=folder)] if d else []):
        try:
            root = ET.parse(p).getroot().find("system")
            for k in ("fullname", "theme", "platform", "manufacturer", "release"):
                e = root.find(k)
                if e is not None and (e.text or "").strip():
                    info[k] = e.text.strip()
        except (OSError, ET.ParseError, AttributeError):
            pass
    return info


def discover_folders(cfg, names):
    """Folders in roms/ that already hold shortcuts to your ports (e.g. a hand-made 'portandroid') become categories.
    Returns the list of folders that were added. `names` = game names found in roms/ports."""
    roms, added, known = get_path(cfg, "roms_dir"), [], {c["folder"] for c in cfg["categories"]}
    if not roms or not roms.is_dir():
        return added
    skip = {"ports", "tools", "ports_scripts"} | set(core_skip(cfg))
    for d in sorted(roms.iterdir()):
        if not d.is_dir() or d.name in known or d.name in skip or d.name.startswith(".") or not FOLDER_RE.match(d.name):
            continue
        hit = False
        for f in d.glob("*.sh"):
            try:
                txt = f.read_text(encoding="utf-8", errors="ignore")
            except OSError:
                continue
            if f.name in names or "/ports/" in txt:
                hit = True
                break
        if hit:
            i = _cfg_info(cfg, d.name)
            theme = i.get("theme", "ports")
            cfg["categories"].append({"folder": d.name, "name": i.get("fullname", d.name), "manufacturer": i.get("manufacturer", "Various"),
                                      "release": i.get("release", "2000"), "platform": i.get("platform", platform_for_theme(theme)), "theme": theme})
            added.append(d.name)
    return added


def core_skip(cfg):
    return [x.strip() for x in cfg.get("skip_folders", []) if x.strip()]


def scan_existing(cfg):
    """{original_sh_name: category_folder} read from the shortcuts that already exist (ours or hand-made)."""
    found = {}
    roms = get_path(cfg, "roms_dir")
    if not roms:
        return found
    names = set(list_games(cfg))
    for cat in cfg["categories"]:
        d = roms / cat["folder"]
        if not d.is_dir():
            continue
        for f in d.glob("*.sh"):
            try:
                key = shortcut_key(f.read_text(encoding="utf-8", errors="ignore"))
            except OSError:
                continue
            if key:
                found[key] = cat["folder"]
            elif f.name in names:      # hand-made shortcut with the same file name as the game
                found.setdefault(f.name, cat["folder"])
    return found


# ----------------------------------------------------------------------------
# STEAM
# ----------------------------------------------------------------------------
def http_get(url, timeout=30):
    req = urllib.request.Request(url, headers={"User-Agent": UA, "Accept-Language": "en"})
    with urllib.request.urlopen(req, timeout=timeout) as r:
        return r.read()


def http_json(url):
    return json.loads(http_get(url).decode("utf-8"))


def norm(s):
    return re.sub(r"[^a-z0-9]", "", s.lower())


def steam_search(term):
    url = "https://store.steampowered.com/api/storesearch/?term=%s&l=english&cc=us" % urllib.parse.quote(term)
    items = http_json(url).get("items", [])
    return [(str(i["id"]), i["name"]) for i in items if i.get("type") == "app"]


def steam_auto_match(term):
    """First result whose name contains the term; None if nothing matches."""
    for sid, name in steam_search(term):
        if norm(term) and norm(term) in norm(name):
            return sid, name
    return None


def steam_details(appid, lang):
    d = http_json("https://store.steampowered.com/api/appdetails?appids=%s&l=%s" % (appid, lang)).get(str(appid), {})
    if not d.get("success"):
        raise RuntimeError("Steam returned no data for AppID %s" % appid)
    return d["data"]


def steam_release_date(appid):
    d = http_json("https://store.steampowered.com/api/appdetails?appids=%s&l=english" % appid).get(str(appid), {})
    if not d.get("success"):
        return None
    s = d["data"].get("release_date", {}).get("date", "")
    for fmt in ("%d %b, %Y", "%b %d, %Y"):
        try:
            return datetime.strptime(s, fmt).strftime("%Y%m%dT000000")
        except ValueError:
            pass
    return None


def steam_review_counts(appid):
    """(positive, total) player reviews on Steam."""
    d = http_json("https://store.steampowered.com/appreviews/%s?json=1&language=all&purchase_type=all&num_per_page=0" % appid)
    q = d.get("query_summary", {})
    return q.get("total_positive", 0), q.get("total_reviews", 0)


def steam_review_excerpts(appid, n=6):
    """A few helpful English player reviews (only used as evidence for the optional AI evaluator)."""
    d = http_json("https://store.steampowered.com/appreviews/%s?json=1&language=english&purchase_type=all&filter=all&num_per_page=%d" % (appid, n))
    return [r.get("review", "") for r in d.get("reviews", []) if r.get("review")]


def fetch_metadata(appid, lang="english", want_reviews=False):
    """Steam facts + EVIDENCE (labels, texts, scores) for genre/description/rating.
    Returns (meta, [(url_thumb, url_full), ...]). Metadata is always English."""
    d = steam_details(appid, "english")
    meta = {
        "name": d.get("name", ""),
        "developer": ", ".join(d.get("developers", [])),
        "publisher": ", ".join(d.get("publishers", [])),
    }
    scores = {}
    if d.get("metacritic"):
        scores["metacritic"] = d["metacritic"]["score"]
    try:
        pos, total = steam_review_counts(appid)
        if total:
            scores["steam_pos"], scores["steam_total"] = pos, total
    except Exception:
        pass
    reviews = []
    if want_reviews:
        try:
            reviews = steam_review_excerpts(appid)
        except Exception:
            reviews = []
    try:
        meta["releasedate"] = steam_release_date(appid) or ""
    except Exception:
        pass
    meta["_evidence"] = {
        "labels": [g.get("description", "") for g in d.get("genres", [])],
        "texts": [("Steam description", d.get("about_the_game") or ""), ("Steam summary", d.get("short_description") or "")],
        "scores": scores,
        "reviews": reviews,
    }
    shots = [(s.get("path_thumbnail"), s.get("path_full")) for s in d.get("screenshots", [])]
    if not shots and d.get("header_image"):
        shots = [(d["header_image"], d["header_image"])]
    return meta, shots


def fetch_shots(appid, lang="english"):
    """Only the screenshot list [(url_thumb, url_full), ...] (lighter than fetch_metadata)."""
    d = steam_details(appid, "english")
    shots = [(s.get("path_thumbnail"), s.get("path_full")) for s in d.get("screenshots", [])]
    if not shots and d.get("header_image"):
        shots = [(d["header_image"], d["header_image"])]
    return shots


# ----------------------------------------------------------------------------
# OTHER SOURCES: Wikipedia/Wikidata (no key), RAWG and Google (optional, need a key)
# ----------------------------------------------------------------------------
GAMELIST_META_TAGS = ("desc", "rating", "releasedate", "genre", "developer", "publisher")
DIRECT_FIELDS = ("name", "releasedate", "developer", "publisher")    # copied from the first source that has them
DERIVED_FIELDS = ("genre", "desc", "rating")                         # built by portmasterforwarder.meta from ALL sources
METADATA_LANG = "english"                                            # all generated metadata is English
_GAME_WORDS = ("game",)


def source_on(cfg, name):
    return bool(cfg.get("sources", {}).get(name, DEFAULT_CONFIG["sources"][name]))


def _trim(text, limit=650):
    text = re.sub(r"\s+", " ", text or "").strip()
    if len(text) <= limit:
        return text
    cut = text[:limit]
    i = max(cut.rfind(". "), cut.rfind("! "), cut.rfind("? "))
    return cut[:i + 1] if i > 200 else cut.rstrip() + "..."


def _wiki_page(term, lang="en"):
    """Find the game's article on Wikipedia (checks that it is about a game and that the title matches)."""
    url = "https://%s.wikipedia.org/w/api.php?action=query&list=search&srlimit=6&format=json&srsearch=%s" % (
        lang, urllib.parse.quote(term))
    for hit in http_json(url).get("query", {}).get("search", []):
        title = hit["title"]
        nt, nq = norm(title), norm(term)
        if not nt or not (nq in nt or (len(nt) > 6 and nt in nq)):
            continue
        page = http_json("https://%s.wikipedia.org/api/rest_v1/page/summary/%s" % (
            lang, urllib.parse.quote(title.replace(" ", "_"), safe="")))
        blob = ((page.get("description") or "") + " " + (page.get("extract") or "")[:300]).lower()
        if page.get("type") == "standard" and any(w in blob for w in _GAME_WORDS):
            return page
    return None


_GAMEPLAY_SECTION = re.compile(r"==\s*(?:Gameplay|Game ?play|Gameplay and mechanics|Mechanics)\s*==\s*\n(.*?)(?=\n==[^=]|\Z)", re.S | re.I)


def _wiki_gameplay(title, lang="en"):
    """Text of the article's 'Gameplay' section (the best evidence for a gameplay description)."""
    url = ("https://%s.wikipedia.org/w/api.php?action=query&prop=extracts&explaintext=1&exsectionformat=wiki"
           "&redirects=1&format=json&titles=%s" % (lang, urllib.parse.quote(title)))
    for page in http_json(url).get("query", {}).get("pages", {}).values():
        m = _GAMEPLAY_SECTION.search(page.get("extract", "") or "")
        if m:
            return re.sub(r"={2,}[^=\n]+={2,}", " ", m.group(1))[:3500]
    return ""


def _wd_time(v):
    m = re.match(r"^\+?(\d{4})-(\d\d)-(\d\d)", v.get("time", ""))
    if not m or m.group(1) == "0000":
        return None
    prec = v.get("precision", 11)
    y, mo, d = m.groups()
    if prec < 10:
        mo = "01"
    if prec < 11:
        d = "01"
    return "%s%s%sT000000" % (y, mo if mo != "00" else "01", d if d != "00" else "01")


def wikidata_fields(qid, langs=("en",)):
    """Release date, developer, publisher + evidence (genre labels, review-score ratios)."""
    langs = list(langs)
    ent = http_json("https://www.wikidata.org/wiki/Special:EntityData/%s.json" % qid)["entities"][qid]["claims"]

    def vals(p):
        return [c["mainsnak"]["datavalue"]["value"] for c in ent.get(p, []) if c.get("mainsnak", {}).get("datavalue")]
    out = {}
    dates = sorted(d for d in (_wd_time(v) for v in vals("P577") if isinstance(v, dict)) if d)
    if dates:
        out["releasedate"] = dates[0]
    ids = {"P136": [v["id"] for v in vals("P136") if isinstance(v, dict) and "id" in v][:4],
           "P178": [v["id"] for v in vals("P178") if isinstance(v, dict) and "id" in v][:1],
           "P123": [v["id"] for v in vals("P123") if isinstance(v, dict) and "id" in v][:1]}
    allids = [i for lst in ids.values() for i in lst]
    labels = []
    if allids:
        lab = http_json("https://www.wikidata.org/w/api.php?action=wbgetentities&props=labels&format=json&languages=%s&ids=%s" % (
            urllib.parse.quote("|".join(langs)), urllib.parse.quote("|".join(allids)))).get("entities", {})

        def label(i):
            for lg in langs:
                t = lab.get(i, {}).get("labels", {}).get(lg, {}).get("value")
                if t:
                    return t
            return ""
        labels = [x for x in (label(i) for i in ids["P136"]) if x]
        for p, tag in (("P178", "developer"), ("P123", "publisher")):
            if ids[p]:
                out[tag] = label(ids[p][0])
    ratios = []
    for v in vals("P444"):
        if isinstance(v, str):
            m = re.match(r"^\s*(\d+(?:[.,]\d+)?)\s*(?:/\s*(\d+(?:[.,]\d+)?)|%)\s*$", v)
            if m:
                num = float(m.group(1).replace(",", "."))
                den = float(m.group(2).replace(",", ".")) if m.group(2) else 100.0
                if den > 0 and 0 <= num <= den:
                    ratios.append(num / den)
    out["_labels"], out["_ratios"] = labels, ratios
    return out


def wiki_metadata(term, cfg_lang="english"):
    """English Wikipedia + Wikidata. Returns facts plus '_evidence' for genre/description/rating."""
    page = _wiki_page(term, "en")
    if not page:
        return {}
    out, texts, labels, scores = {}, [], [], {}
    try:
        gp = _wiki_gameplay(page.get("title", term), "en")
        if gp:
            texts.append(("Wikipedia gameplay section", gp))
    except Exception:
        pass
    if page.get("extract"):
        texts.append(("Wikipedia summary", page["extract"]))
    qid = page.get("wikibase_item")
    if qid:
        try:
            wd = wikidata_fields(qid, ("en",))
            labels = wd.pop("_labels", [])
            ratios = wd.pop("_ratios", [])
            if ratios:
                scores["wikidata"] = ratios
            out.update(wd)
        except Exception:
            pass
    out["_evidence"] = {"labels": labels, "texts": texts, "scores": scores}
    return out


def rawg_metadata(term, key):
    d = http_json("https://api.rawg.io/api/games?key=%s&search=%s&page_size=5" % (key, urllib.parse.quote(term)))
    for r in d.get("results", []):
        if norm(term) in norm(r.get("name", "")) or norm(r.get("name", "")) in norm(term):
            det = http_json("https://api.rawg.io/api/games/%s?key=%s" % (r["id"], key))
            out = {}
            if det.get("released"):
                out["releasedate"] = det["released"].replace("-", "") + "T000000"
            if det.get("developers"):
                out["developer"] = ", ".join(x["name"] for x in det["developers"][:2])
            if det.get("publishers"):
                out["publisher"] = ", ".join(x["name"] for x in det["publishers"][:2])
            scores = {}
            if det.get("metacritic"):
                scores["metacritic"] = det["metacritic"]
            if det.get("rating"):
                scores["rawg_rating"], scores["rawg_count"] = det["rating"], det.get("ratings_count", 0)
            out["_evidence"] = {"labels": [g["name"] for g in det.get("genres", [])],
                                "texts": [("RAWG description", det.get("description_raw", ""))], "scores": scores}
            if det.get("background_image"):
                out["_shot"] = det["background_image"]
            return out
    return {}


def google_metadata(term, key, cx, lang="english"):
    """Google Programmable Search: tries a rating (aggregaterating) and short text from the results."""
    d = http_json("https://www.googleapis.com/customsearch/v1?key=%s&cx=%s&num=6&hl=en&q=%s" % (
        key, cx, urllib.parse.quote(term + " video game")))
    scores, texts = {}, []
    for it in d.get("items", []):
        pm = it.get("pagemap", {})
        if "google" not in scores:
            for ar in pm.get("aggregaterating", []):
                try:
                    v, best = float(str(ar["ratingvalue"]).replace(",", ".")), float(str(ar.get("bestrating", 5)).replace(",", "."))
                    if best > 0 and 0 <= v <= best:
                        scores["google"] = v / best
                        break
                except (KeyError, ValueError):
                    pass
        og = (pm.get("metatags") or [{}])[0].get("og:description") or it.get("snippet")
        if og and len(og) > 60:
            texts.append(("Google result", og))
    return {"_evidence": {"labels": [], "texts": texts, "scores": scores}}


def _merge_evidence(acc, ev):
    for lab in ev.get("labels", []):
        if lab and lab not in acc["labels"]:
            acc["labels"].append(lab)
    acc["texts"].extend(ev.get("texts", []))
    acc["reviews"].extend(ev.get("reviews", []))
    for k, v in ev.get("scores", {}).items():
        if k == "wikidata":
            acc["scores"].setdefault("wikidata", []).extend(v)
        elif k not in acc["scores"]:          # first source wins (Steam before RAWG, etc.)
            acc["scores"][k] = v


AI_POST = None   # tests can inject a fake HTTP poster here

SOURCES = ("steam", "wikipedia", "rawg", "google")        # order used by "Auto" (first source that has a fact wins)
SOURCE_NAMES = {"steam": "Steam", "wikipedia": "Wikipedia/Wikidata", "rawg": "RAWG", "google": "Google"}
BLOCK_FIELDS = ("genre", "rating", "desc", "releasedate", "developer", "publisher")   # the editable metadata blocks
FACT_FIELDS = ("releasedate", "developer", "publisher")                                # facts: Google/AI cannot provide them


def ai_settings(cfg):
    if cfg.get("ai_enabled") and cfg.get("anthropic_key"):
        return {"key": cfg["anthropic_key"], "model": cfg.get("ai_model") or pm.AI_DEFAULT_MODEL}
    return None


def enabled_sources(cfg):
    """Sources that are switched on AND usable (RAWG/Google need their keys)."""
    out = []
    for s in SOURCES:
        if not source_on(cfg, s):
            continue
        if s == "rawg" and not cfg.get("rawg_key"):
            continue
        if s == "google" and not (cfg.get("google_key") and cfg.get("google_cx")):
            continue
        out.append(s)
    return out


def sources_for_field(tag):
    """Source keys a block may use: 'auto', 'keep', the real sources and (for derived fields) 'ai'."""
    srcs = ["auto"] + [s for s in SOURCES if not (tag in FACT_FIELDS and s == "google")]
    if tag in DERIVED_FIELDS:
        srcs.append("ai")
    return srcs + ["keep"]


def collect_sources(cfg, nome, st, sid, which, need_shots=False, log=print):
    """Query the given sources once. Returns ({source: {'facts':..., 'evidence':..., 'shot':...}}, steam_shots)."""
    term = st["steam_term"] or default_term(nome)
    ai = ai_settings(cfg)
    collected, shots = {}, []

    def store(src, data):
        collected[src] = {"facts": {k: data[k] for k in ("name",) + FACT_FIELDS if data.get(k)},
                          "evidence": data.get("_evidence") or {"labels": [], "texts": [], "scores": {}},
                          "shot": data.get("_shot")}

    if sid and "steam" in which and source_on(cfg, "steam"):
        try:
            meta, shots = fetch_metadata(sid, METADATA_LANG, want_reviews=bool(ai))
            store("steam", meta)
        except Exception as e:
            log("[%s] Steam failed (%s)" % (nome, e))
    elif sid and need_shots and source_on(cfg, "steam"):
        try:
            shots = fetch_shots(sid)
        except Exception as e:
            log("[%s] Steam failed (%s)" % (nome, e))
    if "wikipedia" in which and source_on(cfg, "wikipedia"):
        try:
            store("wikipedia", wiki_metadata(term))
        except Exception as e:
            log("[%s] Wikipedia failed (%s)" % (nome, e))
    if "rawg" in which and "rawg" in enabled_sources(cfg):
        try:
            store("rawg", rawg_metadata(term, cfg["rawg_key"]))
        except Exception as e:
            log("[%s] RAWG failed (%s)" % (nome, e))
    if "google" in which and "google" in enabled_sources(cfg):
        try:
            store("google", google_metadata(term, cfg["google_key"], cfg["google_cx"]))
        except Exception as e:
            log("[%s] Google failed (%s)" % (nome, e))
    return collected, shots


def _evidence_of(collected, srcs, title):
    ev = {"title": title, "labels": [], "texts": [], "scores": {}, "reviews": []}
    for s in srcs:
        if s in collected:
            _merge_evidence(ev, collected[s]["evidence"])
    return ev


def resolve_field(cfg, nome, term, tag, source, collected, ai_state, log=print):
    """Value of ONE field from the chosen source ('auto' = all sources together). '' when nothing reliable exists."""
    if tag in ("name",) + FACT_FIELDS:
        order = [source] if source in SOURCES else list(SOURCES)
        for s in order:
            v = collected.get(s, {}).get("facts", {}).get(tag)
            if v:
                return v
        return ""
    # derived fields: genre / description / rating
    srcs = [source] if source in SOURCES else list(SOURCES)
    ev = _evidence_of(collected, srcs, term)
    ai_res = None
    if source == "ai" or (source == "auto" and ai_settings(cfg)):
        if "res" not in ai_state:
            full = _evidence_of(collected, list(SOURCES), term)
            ai_state["res"] = pm.run_ai(full, ai_settings(cfg), AI_POST or pm._http_post_json, lambda m: log("[%s] %s" % (nome, m)))
        ai_res = ai_state["res"]
        if source == "ai":
            if not ai_settings(cfg):
                log("[%s] AI evaluation is not configured (Options > AI evaluation)" % nome)
                return ""
            if ai_res is None:
                return ""
            ev = _evidence_of(collected, list(SOURCES), term)
    min_ev = pm.MIN_EVIDENCE if source in ("auto", "ai") else 0.35
    return pm.build_metadata(ev, {tag}, ai_res=ai_res, min_evidence=min_ev).get(tag, "")


def gather_metadata(cfg, nome, st, sid, missing, need_shots, log=print, plan=None):
    """Collect facts + evidence and build the requested fields.

    plan maps field -> source ('auto', 'steam', 'wikipedia', 'rawg', 'google', 'ai'); missing fields default to 'auto'.
    plan['_image'] chooses where screenshots come from ('auto', 'steam', 'rawg').
    Genre, description and rating are derived by portmasterforwarder.meta; fields that cannot be built reliably are left out.
    Returns (fields, [(thumb, full), ...])."""
    plan = dict(plan or {})
    pref = plan.pop("_image", "auto")
    term = st["steam_term"] or default_term(nome)
    enabled = set(enabled_sources(cfg))
    which = set()
    for tag in missing:
        src = plan.get(tag, "auto")
        if src in ("auto", "ai"):
            which |= enabled
        elif src in SOURCES:
            if src in enabled:
                which.add(src)
            else:
                log("[%s] %s is switched off or needs a key (Options); cannot fetch %s" % (nome, SOURCE_NAMES[src], tag))
    if need_shots and pref == "rawg" and "rawg" in enabled:
        which.add("rawg")
    collected, shots = collect_sources(cfg, nome, st, sid, which, need_shots and pref != "rawg", log)
    if need_shots and "rawg" in enabled and (pref == "rawg" or (pref == "auto" and not shots)):
        if "rawg" not in collected:
            more, _ = collect_sources(cfg, nome, st, sid, {"rawg"}, False, log)
            collected.update(more)
        bg = collected.get("rawg", {}).get("shot")
        shots = [(bg, bg)] if bg else (shots if pref == "auto" else [])
    elif pref == "rawg":
        shots = []

    fields, ai_state = {}, {}
    for tag in sorted(missing):
        src = plan.get(tag, "auto")
        val = resolve_field(cfg, nome, term, tag, src, collected, ai_state, log)
        if val:
            fields[tag] = val
    got = sorted(t for t in fields if t != "name")
    if got:
        log("[%s] found: %s" % (nome, ", ".join(got)))
    lacking = sorted(t for t in missing if t in DERIVED_FIELDS and t not in fields)
    if lacking:
        log("[%s] not enough reliable information for: %s" % (nome, ", ".join(lacking)))
    still = sorted(t for t in missing if t in FACT_FIELDS and t not in fields)
    if still:
        log("[%s] not found: %s" % (nome, ", ".join(still)))
    return fields, shots


def preview_metadata(cfg, nome, log=print):
    """Show what the sources would produce, without writing anything."""
    st = game_state(cfg, nome)
    sid = str(st["steam_id"]).strip()
    if not sid and source_on(cfg, "steam"):
        m = steam_auto_match(st["steam_term"] or default_term(nome))
        sid = m[0] if m else ""
    fields, shots = gather_metadata(cfg, nome, st, sid, set(GAMELIST_META_TAGS) | {"name"}, True, log)
    return sid, fields, len(shots)


def fetch_field(cfg, nome, tag, source="auto", log=print):
    """Fetch ONE field from ONE source (used by the block 'Fetch' buttons). Nothing is written to disk.
    Returns (value, updates) where updates may carry a Steam match found on the way."""
    st = game_state(cfg, nome)
    updates = {}
    sid = str(st["steam_id"]).strip()
    if not sid and source in ("auto", "steam") and source_on(cfg, "steam"):
        m = steam_auto_match(st["steam_term"] or default_term(nome))
        updates["steam_checked"] = True
        if m:
            sid = m[0]
            updates["steam_id"], updates["steam_name"] = m
    fields, _shots = gather_metadata(cfg, nome, st, sid, {tag}, False, log, plan={tag: source})
    return fields.get(tag, ""), updates


def fetch_image_options(cfg, nome, source="steam", log=print):
    """Screenshot choices [(thumb_url, full_url), ...] from Steam or RAWG, plus any Steam match found."""
    st = game_state(cfg, nome)
    updates = {}
    sid = str(st["steam_id"]).strip()
    if source == "rawg":
        if "rawg" not in enabled_sources(cfg):
            log("[%s] RAWG is switched off or needs a key (Options)" % nome)
            return [], updates
        data = rawg_metadata(st["steam_term"] or default_term(nome), cfg["rawg_key"])
        bg = data.get("_shot")
        return ([(bg, bg)] if bg else []), updates
    if not sid and source_on(cfg, "steam"):
        m = steam_auto_match(st["steam_term"] or default_term(nome))
        updates["steam_checked"] = True
        if m:
            sid = m[0]
            updates["steam_id"], updates["steam_name"] = m
    return (fetch_shots(sid) if sid else []), updates


# ----------------------------------------------------------------------------
# PRESETS, PINNED VALUES, NEW CATEGORIES
# ----------------------------------------------------------------------------
def _all(src):
    return {t: src for t in BLOCK_FIELDS}


BUILTIN_PRESETS = {
    "Balanced (all sources)": dict(_all("auto"), image="auto"),
    "Steam": dict(_all("steam"), image="web"),
    "Wikipedia": dict(_all("wikipedia"), image="auto"),
    "RAWG": dict(_all("rawg"), image="rawg"),
    "Google": dict(_all("auto"), genre="google", rating="google", desc="google", image="auto"),
    "AI evaluation": dict(_all("auto"), genre="ai", rating="ai", desc="ai", image="auto"),
    "Keep current": dict(_all("keep"), image="none"),
}


def all_presets(cfg):
    out = {k: dict(v) for k, v in BUILTIN_PRESETS.items()}
    for name, preset in (cfg.get("presets") or {}).items():
        out[name] = dict(preset)
    return out


def apply_preset(st, preset):
    """Set the source of every block from a preset (pinned values of those blocks are cleared)."""
    src = dict(st.get("src") or {})
    manual = dict(st.get("manual") or {})
    for tag in BLOCK_FIELDS:
        if tag in preset:
            src[tag] = preset[tag]
            manual.pop(tag, None)
            if tag in ("desc", "rating", "genre"):
                st[tag] = ""
    st["src"], st["manual"] = src, manual
    if "image" in preset:
        st["shot_mode"] = preset["image"]
    return st


def preset_from_state(st):
    p = {t: (st.get("src") or {}).get(t, "auto") for t in BLOCK_FIELDS}
    p["image"] = st.get("shot_mode", "auto") if st.get("shot_mode") != "local" else "auto"
    return p


def manual_value(st, tag):
    """The value pinned by the user for a block ('' = not pinned). Older versions stored desc/rating/genre directly."""
    v = (st.get("manual") or {}).get(tag, "")
    if not str(v).strip() and tag in ("desc", "rating", "genre"):
        v = st.get(tag, "")
    return str(v).strip()


def normalize_date(text):
    """'2018-01-25', '25/01/2018', '20180125', '2018' -> '20180125T000000' (EmulationStation). None if unreadable."""
    t = str(text).strip()
    if re.fullmatch(r"\d{8}T\d{6}", t):
        return t
    for rx, order in ((r"(\d{4})-(\d{1,2})-(\d{1,2})", "ymd"), (r"(\d{1,2})/(\d{1,2})/(\d{4})", "dmy"), (r"(\d{4})(\d{2})(\d{2})", "ymd")):
        m = re.fullmatch(rx, t)
        if m:
            g = dict(zip(order, m.groups()))
            try:
                datetime(int(g["y"]), int(g["m"]), int(g["d"]))
            except ValueError:
                return None
            return "%04d%02d%02dT000000" % (int(g["y"]), int(g["m"]), int(g["d"]))
    if re.fullmatch(r"\d{4}", t):
        return t + "0101T000000"
    return None


def normalize_manual(tag, value):
    """Validate/normalize a value typed by the user. Returns the string to store, or None if it is not valid."""
    v = str(value).strip()
    if not v:
        return None
    if tag == "genre":
        return pm.canonical_genre(v)
    if tag == "rating":
        try:
            return pm.parse_user_rating(v)
        except ValueError:
            return None
    if tag == "releasedate":
        return normalize_date(v)
    return v


def display_value(tag, es_value):
    """EmulationStation value -> what people see in a block (rating 0-10, date YYYY-MM-DD)."""
    v = (es_value or "").strip()
    if not v:
        return ""
    if tag == "rating":
        try:
            return ("%.1f" % (float(v) * 10)).rstrip("0").rstrip(".") if float(v) * 10 % 1 else "%d" % round(float(v) * 10)
        except ValueError:
            return v
    if tag == "releasedate" and re.match(r"^\d{8}T", v):
        return "%s-%s-%s" % (v[:4], v[4:6], v[6:8])
    return v


def add_category(cfg, name, theme="ports"):
    """Create a new category (menu system) and return it. The folder name is generated safely from the name."""
    name = (name or "").strip()
    if not name:
        raise ValueError("The category needs a name")
    theme = (theme or "ports").strip()
    folder = slug_folder(name, [c["folder"] for c in cfg["categories"]])
    cat = {"folder": folder, "name": name, "manufacturer": "Various", "release": "2000",
           "platform": platform_for_theme(theme), "theme": theme}
    cfg["categories"].append(cat)
    return cat


def update_category(cfg, folder, name=None, theme=None):
    """Rename a category and/or change its icon (theme). The folder never changes, so shortcuts keep working."""
    cat = cat_by_folder(cfg, folder)
    if cat is None:
        raise ValueError("Unknown category")
    if name is not None:
        if not name.strip():
            raise ValueError("The category needs a name")
        cat["name"] = name.strip()
    if theme:
        cat["theme"] = theme.strip()
        cat["platform"] = platform_for_theme(cat["theme"])
    return cat


def normalize_rating(text):
    """Accepts 0.85, 8.5 (0-10) or 85 (0-100) and returns '0.85' (EmulationStation format)."""
    return pm.parse_user_rating(text)


# ----------------------------------------------------------------------------
# IMAGES
# ----------------------------------------------------------------------------
def write_image(raw, dest_noext, max_w):
    """Write the image (resized JPEG when Pillow is available). Returns the file name."""
    dest_noext = Path(dest_noext)
    if HAS_PIL:
        im = Image.open(io.BytesIO(raw)).convert("RGB")
        if im.width > max_w:
            res = getattr(Image, "Resampling", Image).LANCZOS
            im = im.resize((max_w, max(1, int(im.height * max_w / im.width))), res)
        out = Path(str(dest_noext) + ".jpg")
        im.save(out, "JPEG", quality=88)
    else:
        ext = ".png" if raw[:4] == b"\x89PNG" else ".jpg"
        out = Path(str(dest_noext) + ext)
        out.write_bytes(raw)
    return out.name


# ----------------------------------------------------------------------------
# GAMELIST.XML
# ----------------------------------------------------------------------------
_TOUCHED = set()  # gamelists already handled in this session (the .bak is the state BEFORE we changed anything)


def load_gamelist(path):
    path = Path(path)
    first_touch = str(path) not in _TOUCHED
    _TOUCHED.add(str(path))
    if path.exists():
        bak = path.with_name(path.name + ".bak")
        if first_touch and not bak.exists():
            shutil.copy2(path, bak)
        tree = ET.parse(path)
        root = tree.getroot()
    else:
        root = ET.Element("gameList")
        tree = ET.ElementTree(root)
    return tree, root


def find_game(root, rel):
    for g in root.findall("game"):
        p = g.find("path")
        if p is not None and p.text == rel:
            return g
    return None


def set_field(game, tag, value):
    if not value:
        return
    e = game.find(tag)
    if e is None:
        e = ET.SubElement(game, tag)
    e.text = value


def save_gamelist(tree, path):
    ET.indent(tree, space="\t")
    tree.write(path, encoding="utf-8", xml_declaration=True)


def remove_from_gamelist(path, rel):
    path = Path(path)
    if not path.exists():
        return
    tree, root = load_gamelist(path)
    g = find_game(root, rel)
    if g is not None:
        root.remove(g)
        save_gamelist(tree, path)


# ----------------------------------------------------------------------------
# LAUNCHERS (shortcuts to the original scripts)
# ----------------------------------------------------------------------------
def wrapper_text(target, version=None):
    if version:
        d = target.rsplit("/", 1)[0] + "/" + "/".join(MCPE_VERSIONS_REL) + "/" + version
        return ('#!/bin/bash\n%s\n# mcpe-version: %s\nTARGET="%s"\n'
                'if [ ! -f "$TARGET" ]; then\n    echo "Original script not found: $TARGET"\n    exit 1\nfi\n'
                'if [ ! -d "%s" ]; then\n    echo "MCPE version not found: %s"\n    exit 1\nfi\n'
                'exec bash "$TARGET" "%s"\n') % (MARK, version, target, d, version, version)
    return ('#!/bin/bash\n%s\nTARGET="%s"\n'
            'if [ ! -f "$TARGET" ]; then\n    echo "Original script not found: $TARGET"\n    exit 1\nfi\n'
            'exec bash "$TARGET" "$@"\n') % (MARK, target)


def write_text_lf(path, text):
    with open(path, "w", encoding="utf-8", newline="\n") as f:
        f.write(text)


def effective_meta_mode(cfg, st):
    m = st.get("meta_mode", "follow")
    if m in ("keep", "replace"):
        return m
    return "replace" if cfg.get("meta_global") == "replace" else "fill"


def _present(game, cdir, base):
    """Fields the gamelist entry already has (an image only counts if the file exists)."""
    out = set()
    if game is None:
        return out
    for t in GAMELIST_META_TAGS + ("image",):
        e = game.find(t)
        if e is not None and (e.text or "").strip():
            if t == "image" and not (cdir / e.text.strip()).exists():
                continue
            out.add(t)
    n = game.find("name")
    if n is not None and (n.text or "").strip() and n.text.strip() != base:
        out.add("name")
    return out


def _read_entry(cfg, nome):
    st = game_state(cfg, nome)
    cat = cat_by_folder(cfg, st["cat"])
    if not cat:
        return None, None, None
    cdir = cat_dir(cfg, cat)
    base = nome[:-3] if nome.lower().endswith(".sh") else nome
    try:
        root = ET.parse(cdir / "gamelist.xml").getroot()
    except (OSError, ET.ParseError):
        return None, cdir, base
    return find_game(root, "./" + nome), cdir, base


def existing_meta(cfg, nome):
    """What the category gamelist already has for this game (nothing is modified)."""
    game, cdir, base = _read_entry(cfg, nome)
    return _present(game, cdir, base) if cdir else set()


def nonstandard_fields(cfg, nome):
    """Existing values that break the PortMasterForwarder rules (currently: genre outside the standard list)."""
    game, _cdir, _base = _read_entry(cfg, nome)
    out = []
    if game is not None:
        g = game.find("genre")
        if g is not None and (g.text or "").strip() and not pm.is_standard_genre(g.text.strip()):
            out.append("genre")
    return out


def existing_entry(cfg, nome):
    """The gamelist entry of this game as {tag: text} ({} if there is none). Nothing is modified."""
    game, _cdir, _base = _read_entry(cfg, nome)
    return {c.tag: (c.text or "").strip() for c in game} if game is not None else {}


def existing_image_path(cfg, nome):
    """Path of the image the gamelist already uses for this game (None if missing)."""
    game, cdir, _base = _read_entry(cfg, nome)
    if game is None:
        return None
    e = game.find("image")
    if e is None or not (e.text or "").strip():
        return None
    p = cdir / e.text.strip()
    return p if p.exists() else None


def plan_fields(cfg, st, present, rewrite=False):
    """Decide, per block, what Apply will do. Returns ({field: source_to_fetch}, {field: pinned_value})."""
    mode = effective_meta_mode(cfg, st)
    src_map = st.get("src") or {}
    fetch, pinned = {}, {}
    for tag in BLOCK_FIELDS:
        v = manual_value(st, tag)
        if v:
            # your typed value overwrites what is there only when saving ONE game (rewrite) or in replace mode
            if rewrite or mode == "replace" or tag not in present:
                pinned[tag] = v
            continue
        s = src_map.get(tag, "auto")
        if s in ("keep", "manual"):
            continue
        if s == "auto":
            if mode == "keep" or (mode == "fill" and tag in present):
                continue
            fetch[tag] = "auto"
        else:
            fetch[tag] = s          # an explicitly chosen source replaces the current value
    if mode == "replace" or (mode == "fill" and "name" not in present):
        fetch["name"] = "auto"
    return fetch, pinned


def apply_game(cfg, nome, log=print, rewrite=False):
    """Create shortcut + gamelist entry + screenshot for ONE game.
    Each metadata block follows its own source / pinned value; 'auto' blocks follow the metadata mode (fill/replace/keep).
    Returns a dict of discovered fields (e.g. steam_id) that the app should remember."""
    updates = {}
    st = game_state(cfg, nome)
    cat = cat_by_folder(cfg, st["cat"])
    if not cat:
        log("[%s] no category, skipped" % nome)
        return updates
    if re.search(r'[$`"\\]', nome):
        log("[%s] unsupported character in file name ($ ` \" \\), skipped" % nome)
        return updates

    base = nome[:-3] if nome.lower().endswith(".sh") else nome
    rel = "./" + nome
    cdir = cat_dir(cfg, cat)
    cdir.mkdir(parents=True, exist_ok=True)

    # 1) shortcut (a launcher you wrote by hand is never overwritten)
    target_file = cdir / nome
    if target_file.exists() and not is_ours(target_file.read_text(encoding="utf-8", errors="ignore")):
        log("[%s] existing launcher kept (it was not created by PortMasterForwarder)" % nome)
    else:
        script, ver = mcpe_virtual(cfg).get(nome, (nome, None))
        write_text_lf(target_file, wrapper_text(device_ports_path(cfg) + "/" + script, ver))
        log("[%s] shortcut created in %s" % (nome, cat["name"]))

    # 2) remove from other categories (only shortcuts that point to this game)
    for other in cfg["categories"]:
        if other["folder"] == cat["folder"]:
            continue
        f = cat_dir(cfg, other) / nome
        if f.exists():
            if shortcut_key(f.read_text(encoding="utf-8", errors="ignore")) == nome:
                f.unlink()
                remove_from_gamelist(cat_dir(cfg, other) / "gamelist.xml", rel)
                log("[%s] removed from %s" % (nome, other["name"]))

    # 3) what already exists and what each block will do
    tree, root = load_gamelist(cdir / "gamelist.xml")
    game = find_game(root, rel)
    present = _present(game, cdir, base)
    if game is None:
        game = ET.SubElement(root, "game")
        set_field(game, "path", rel)
        set_field(game, "name", base)

    mode = effective_meta_mode(cfg, st)
    fetch, pinned = plan_fields(cfg, st, present, rewrite)
    if not (set(fetch) - {"name"}) and not pinned:
        log("[%s] metadata: %s" % (nome, "keep (not touched)" if mode == "keep" else "already complete, kept"))
    if mode == "fill" and "genre" in present and "genre" not in pinned and (st.get("src") or {}).get("genre", "auto") == "auto":
        g = game.find("genre").text.strip()
        if not pm.is_standard_genre(g):
            log("[%s] existing genre '%s' is not a standard genre (kept; use 'Replace' to standardize)" % (nome, g))

    shot_mode = st["shot_mode"]
    explicit_img = shot_mode in ("web", "local", "rawg")
    img_wanted = shot_mode != "none" and (explicit_img or "image" not in present)

    # 4) Steam (find the game, if not looked up yet) - only when something needs it
    sid = str(st["steam_id"]).strip()
    uses_steam = any(s in ("auto", "steam", "ai") for s in fetch.values()) or (img_wanted and shot_mode in ("auto", "web"))
    if not sid and not st.get("steam_checked") and uses_steam and source_on(cfg, "steam"):
        try:
            m = steam_auto_match(st["steam_term"] or default_term(nome))
        except Exception as e:
            m = None
            log("[%s] Steam search failed (%s)" % (nome, e))
        updates["steam_checked"] = True
        if m:
            sid = m[0]
            updates["steam_id"], updates["steam_name"] = m
            log("[%s] found on Steam: %s" % (nome, m[1]))
        else:
            log("[%s] not on Steam" % nome)

    # 5) fetch what is planned, then apply pinned (user) values on top
    fields, shots = {}, []
    if fetch or img_wanted:
        plan = dict(fetch)
        plan["_image"] = {"web": "steam", "rawg": "rawg"}.get(shot_mode, "auto")
        fields, shots = gather_metadata(cfg, nome, st, sid, set(fetch), img_wanted, log, plan=plan)
    for tag, raw_value in pinned.items():
        value = normalize_manual(tag, raw_value)
        if value is None:
            log("[%s] pinned %s %r is not valid, ignored" % (nome, tag, raw_value))
            continue
        if tag == "desc" and not pm.validate_description(value)[0]:
            log("[%s] note: your description mentions non-gameplay details or is not English (kept as you wrote it)" % nome)
        fields[tag] = value
    if "genre" in fields and not pm.is_standard_genre(fields["genre"]):
        fields.pop("genre")   # safety net: only standard genres are ever written
    for tag, val in fields.items():
        set_field(game, tag, val)

    # 6) screenshot
    raw = None
    if img_wanted:
        try:
            if shot_mode == "local":
                if st["shot_local"]:
                    raw = Path(st["shot_local"]).read_bytes()
            elif shots:   # auto, web (Steam) or rawg
                idx = min(int(st["shot_idx"]), len(shots) - 1) if shot_mode == "web" else 0
                thumb, full = shots[idx]
                try:
                    raw = http_get(full)
                except Exception:
                    raw = http_get(thumb)
            elif shot_mode in ("web", "rawg"):
                log("[%s] no image available online" % nome)
        except Exception as e:
            log("[%s] FAILED to get screenshot (%s)" % (nome, e))
    elif shot_mode != "none":
        log("[%s] image already exists, kept" % nome)
    if raw:
        imgdir = cdir / cfg["images_subdir"]
        imgdir.mkdir(parents=True, exist_ok=True)
        fname = write_image(raw, imgdir / (base + "-image"), int(cfg["screenshot_max_width"]))
        set_field(game, "image", "./%s/%s" % (cfg["images_subdir"], fname))
        log("[%s] screenshot saved (%s)" % (nome, fname))

    save_gamelist(tree, cdir / "gamelist.xml")
    return updates


def apply_all(cfg, log=print):
    """Apply every game that has a category. Returns {name: updates} for the app to remember."""
    gone = _drop_stale_mcpe(cfg, log)
    names = [n for n, s in cfg["games"].items() if s.get("cat") and n not in gone]
    result = {}
    for n in names:
        try:
            result[n] = apply_game(cfg, n, log)
        except Exception as e:
            log("[%s] ERROR: %s" % (n, e))
    log("Done (%d game(s))." % len(names))
    return result


def _drop_stale_mcpe(cfg, log=print):
    """Remove our MCPE version shortcuts whose version folder no longer exists (hand-made files are never touched)."""
    ports = get_path(cfg, "ports_dir")
    gone = set()
    if not ports or not ports.joinpath(*MCPE_VERSIONS_REL).is_dir():
        return gone
    alive = set(mcpe_virtual(cfg))
    for cat in cfg["categories"]:
        d = cat_dir(cfg, cat)
        for f in (d.glob("*.sh") if d.is_dir() else []):
            text = f.read_text(encoding="utf-8", errors="ignore")
            if is_ours(text) and VERSION_RE.search(text) and shortcut_key(text) not in alive:
                f.unlink()
                remove_from_gamelist(d / "gamelist.xml", "./" + f.name)
                gone.add(shortcut_key(text))
                log("[%s] MCPE version no longer installed, shortcut removed" % f.name)
    return gone


def remove_wrappers(cfg, log=print):
    """Delete only shortcuts created by this app (marked). Gamelists and images are not touched."""
    n = 0
    for cat in cfg["categories"]:
        d = cat_dir(cfg, cat)
        if d.is_dir():
            for f in d.glob("*.sh"):
                if is_ours(f.read_text(encoding="utf-8", errors="ignore")):
                    f.unlink()
                    n += 1
    log("%d shortcut(s) removed." % n)


# ----------------------------------------------------------------------------
# MENU SYSTEMS (es_systems_*.cfg)
# ----------------------------------------------------------------------------
def _esc(s):
    return (str(s).replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;"))


def system_xml(cfg, cat):
    return """<?xml version="1.0"?>
%s
<systemList>
    <system>
        <fullname>%s</fullname>
        <name>%s</name>
        <manufacturer>%s</manufacturer>
        <release>%s</release>
        <hardware>console</hardware>
        <path>%s/%s</path>
        <extension>.sh</extension>
        <command>%s</command>
        <platform>%s</platform>
        <theme>%s</theme>
    </system>
</systemList>
""" % (XML_MARK, _esc(cat["name"]), _esc(cat["folder"]), _esc(cat["manufacturer"]), _esc(cat["release"]),
       _esc(profile(cfg)["device_roms"]), _esc(cat["folder"]), _esc(profile(cfg)["es_command"]), _esc(cat["platform"]), _esc(cat["theme"]))


def system_cfg_path(cfg, cat):
    return get_path(cfg, "es_cfg_dir") / profile(cfg)["system_cfg"].format(folder=cat["folder"])


def foreign_cfgs(cfg):
    """Existing cfg files NOT created by this app (e.g. ones you wrote by hand)."""
    out = []
    for cat in cfg["categories"]:
        p = system_cfg_path(cfg, cat)
        if p.exists() and not is_ours_xml(p.read_text(encoding="utf-8", errors="ignore")):
            out.append(p)
    return out


def install_systems(cfg, overwrite_foreign=False, log=print, only=None):
    for cat in cfg["categories"]:
        if only and cat["folder"] != only:
            continue
        if not FOLDER_RE.match(cat["folder"]):
            log("Invalid folder '%s' (use a-z, 0-9, _ and -). Skipped." % cat["folder"])
            continue
        p = system_cfg_path(cfg, cat)
        if p.exists() and not is_ours_xml(p.read_text(encoding="utf-8", errors="ignore")) and not overwrite_foreign:
            log("Kept (already existed): %s" % p.name)
            continue
        p.parent.mkdir(parents=True, exist_ok=True)
        write_text_lf(p, system_xml(cfg, cat))
        cat_dir(cfg, cat).mkdir(parents=True, exist_ok=True)
        log("Installed: %s" % p.name)
    log("Restart Knulli (Menu > Quit > Restart System). Systems with no games stay hidden.")


def remove_systems(cfg, remove_foreign=False, log=print):
    for cat in cfg["categories"]:
        p = system_cfg_path(cfg, cat)
        if not p.exists():
            continue
        ours = is_ours_xml(p.read_text(encoding="utf-8", errors="ignore"))
        if ours or remove_foreign:
            p.unlink()
            log("Removed: %s" % p.name)
        else:
            log("Kept (not created by this app): %s" % p.name)
